<?php

declare(strict_types=1);

namespace App\Modules\Identity\Support;

/**
 * The menu tree as the code knows it (AnnotechERP 02/01). SyncMenus writes it
 * to menu_modules/menus/menu_permissions; an admin may then rename, reorder
 * and hide entries, but only code adds a screen.
 *
 * Every leaf names:
 *  - `view`: the permission(s) that put it in someone's sidebar — exactly the
 *    string the screen's own API checks, so nobody is offered a link the
 *    backend would refuse (null = every signed-in user);
 *  - `prefixes`: permission families whose other verbs become the menu's
 *    C/E/D/A/X flags (see FLAG_BY_VERB).
 *
 * Labels name a `nav.*` translation key so English and Bangla come from the
 * same lang files the rest of the UI uses.
 */
final class MenuRegistry
{
    /** The last segment of a permission → Brickland's grant column. */
    public const FLAG_BY_VERB = [
        'view' => 'V', 'view_any' => 'V',
        'create' => 'C', 'request' => 'C',
        'delete' => 'D',
        'approve' => 'A', 'reject' => 'A', 'post' => 'A', 'verify' => 'A', 'publish' => 'A',
        'print' => 'P',
        'export' => 'X',
        // anything else (update, manage, issue, receive, close, cancel …) is an Edit
    ];

    /**
     * Brickland's sidebar sections, in its order; a module sits in one.
     * MAINTENANCE is ours — Brickland has no machinery module.
     */
    public const SECTIONS = [
        'OVERVIEW', 'SYSTEM_ADMINISTRATION', 'HUMAN_RESOURCE', 'SALES_MERCHANDISING', 'PRE_BUDGET', 'PLANNING', 'PRODUCTION',
        'INVENTORY_STORES', 'FINANCE_ACCOUNTING', 'COMMERCIAL_EXPORT', 'INDUSTRIAL_ENGINEERING', 'LABORATORY', 'MAINTENANCE',
    ];

    /**
     * Permission families of the old project's modules that the ERP no longer
     * shows (Procurement, Store / Item Library, Compliance, Production Orders,
