    /**
     * Leaves: [code, module, folder|null, label key, url, icon, view, prefixes, in sidebar].
     *
     * @return list<array{0: string, 1: string, 2: ?string, 3: string, 4: string, 5: string, 6: string|list<string>|null, 7: list<string>, 8: bool}>
     */
    public static function menus(): array
    {
        $company = static fn (string $key, ?string $folder, string $icon, string|array|null $view, array $prefixes): array => [
            'COMPANY.'.strtoupper(str_replace('-', '_', $key)), 'COMPANY', $folder, 'company.tabs.'.$key, '/company-management/'.$key, $icon, $view, $prefixes, true,
        ];
        $settings = static fn (string $code, string $folder, string $key, string $icon, string|array|null $view, array $prefixes): array => [
            'SETTINGS.'.$code, 'SETTINGS', $folder, 'settings.hub.screens.'.$key, '/system-settings/'.$key, $icon, $view, $prefixes, true,
        ];
        $merch = static fn (string $code, string $key, string $icon): array => [
            'MERCHANDISE.'.$code, 'MERCHANDISE', 'MERCHANDISE.MASTER_DATA', 'merchandise.master.screens.'.$key, '/merchandise-desk/'.$key, $icon, ['merchandise.master.view', 'merchandise.master.manage'], [], true,
        ];
        $approval = static fn (string $code, string $folder, string $key, string $icon, string|array|null $view): array => [
            'APPROVAL.'.$code, 'APPROVAL', $folder, 'approval.center.screens.'.$key, '/approval-center/'.$key, $icon, $view, [], true,
        ];
        $access = static fn (string $code, string $folder, string $key, string $icon, string|array|null $view, array $prefixes): array => [
            'ACCESS.'.$code, 'ACCESS', $folder, 'access.tabs.'.$key, '/access-control/'.$key, $icon, $view, $prefixes, true,
        ];

        return [

            // Company Management, as Brickland's sidebar has it: Dashboard,
            // Company Profile, four folders, Company Documents.
            ['COMPANY.HOME', 'COMPANY', null, 'nav.dashboard', '/company-management', 'LayoutDashboard', 'masterdata.manage', ['masterdata'], true],
            $company('company-profile', null, 'Building2', 'settings.company.manage', ['settings.company']),
