            ['SETTINGS.APPROVAL_WORKFLOWS', 'SETTINGS', 'SETTINGS.OTHER', 'nav.approval_workflows', '/settings/approval-workflows', 'GitBranch', 'settings.company.manage', [], false],
            ['SETTINGS.ESCALATIONS', 'SETTINGS', 'SETTINGS.OTHER', 'nav.escalations', '/settings/escalations', 'BellRing', 'settings.company.manage', [], true],
            ['SETTINGS.WEBHOOKS', 'SETTINGS', 'SETTINGS.OTHER', 'nav.webhooks', '/settings/webhooks', 'Webhook', 'webhook.endpoint.manage', ['webhook'], false],
            ['SETTINGS.API_CLIENTS', 'SETTINGS', 'SETTINGS.OTHER', 'nav.api_clients', '/settings/api-clients', 'KeyRound', 'admin.api_client.manage', ['admin.api_client'], false],
        ];
    }

    /** A module's section, for modules the registry knows. */
    public static function sectionOf(string $moduleCode): string
    {
        return self::modules()[$moduleCode][3] ?? 'OVERVIEW';
    }

    /** V/C/E/D/A/P/X for one permission name. */
    /**
     * screen code => the permissions that open it (any one); [] = every signed-in user.
     *
     * @return array<string, list<string>>
     */
    public static function gates(): array
    {
        static $gates = null;
        if ($gates === null) {
            $gates = [];
            foreach (self::menus() as [$code, , , , , , $view]) {
                $gates[$code] = array_values(array_filter((array) $view));
            }
        }

        return $gates;
    }

    public static function flagFor(string $permission): string
    {
        $verb = substr($permission, (int) strrpos($permission, '.') + 1);

        return self::FLAG_BY_VERB[$verb] ?? 'E';
    }
}
